-- Topic: Written Representations
-- Difficulty: 9E / 15M / 6H
-- Bloom's: L1:8 / L2:9 / L3:8 / L4:5

BEGIN;

INSERT INTO questions (section_id, topic, stem, choices, correct_index, explanation, difficulty, cognitive_level)
VALUES

-- Q1: medium / L3 — Completeness representation as complement to other evidence
(1, 'Written Representations', 'During the audit of Meridian Healthcare Corp. for the year ended December 31, 2025, the engagement team at Ashford & Bell CPA obtains management''s written representation that all transactions have been recorded and reflected in the financial statements. The senior auditor asks whether this completeness representation alone provides sufficient appropriate evidence for the completeness assertion. Under AU-C 580, the auditor should:', '["Accept the completeness representation as sufficient evidence because management has direct knowledge of all transactions", "Use the completeness representation to complement other audit evidence, as written representations alone do not provide sufficient appropriate evidence for any assertion", "Rely on the completeness representation for immaterial account balances but perform additional procedures for material balances", "Request the representation be notarized to increase its evidentiary value"]'::jsonb, 1, 'AU-C 580.04 states that written representations are necessary audit information but do not provide sufficient appropriate evidence on their own for any assertion. The auditor must obtain corroborating evidence through other audit procedures. Unlike choice A suggests, management''s representations—even about completeness—cannot substitute for substantive testing or other procedures.', 'medium', 3),

-- Q2: medium / L2 — Period covered by the representation letter
(1, 'Written Representations', 'Greystone Manufacturing retained a new auditor, Palmer & Quinn LLP, to audit its financial statements for the year ended December 31, 2025. The controller asks the engagement partner what financial statement periods the management representation letter should cover. Under AU-C 580, the representation letter should cover:', '["Only the current year under audit, as the prior auditor obtained representations for prior periods", "Only periods in which the current auditor performed substantive procedures", "All periods referred to in the auditor''s report, including any comparative periods presented", "The current year plus one additional prior year regardless of comparative presentations"]'::jsonb, 2, 'AU-C 580.15 requires the management representation letter to cover all financial statement periods referred to in the auditor''s report. When comparative financial statements are presented, the letter must address all periods covered by the opinion. Choice A is incorrect because a change of auditor does not eliminate the need for representations covering comparative periods.', 'medium', 2),

-- Q3: medium / L2 — Oral representations not a substitute for written form
(1, 'Written Representations', 'During the audit of Lakewood Industries for the year ended December 31, 2025, the CFO orally informs the engagement team at Donovan & Associates that the company has no undisclosed related party transactions. The engagement partner considers whether this oral assurance is sufficient. Under AU-C 580, oral representations from management are:', '["Acceptable as audit evidence when documented in the auditor''s workpapers", "Sufficient if the auditor includes them in a memorandum to the file", "Acceptable only for immaterial matters that do not affect the auditor''s opinion", "Not a substitute for required written representations and must be confirmed in the representation letter"]'::jsonb, 3, 'AU-C 580.09 requires that representations be in written form. Oral representations do not satisfy the requirement for written representations, regardless of documentation in the auditor''s workpapers. Choice A is incorrect because documenting oral statements in workpapers does not convert them into the written representations required by the standard.', 'medium', 2),

-- Q4: easy / L1 — Primary purpose of the representation letter
(1, 'Written Representations', 'What is the primary purpose of obtaining a management representation letter during an audit?', '["To confirm management''s responsibility for the financial statements and support other audit evidence obtained", "To provide the auditor with an insurance policy against future litigation", "To replace substantive testing for areas where the auditor has limited access", "To satisfy legal requirements imposed by the Securities and Exchange Commission"]'::jsonb, 0, 'AU-C 580.03 establishes that written representations serve to confirm management''s responsibility for the financial statements and to support other audit evidence. They are a necessary part of audit evidence, not a legal formality. Choice B is incorrect because the letter does not function as insurance—it is an evidentiary tool.', 'easy', 1),

-- Q5: medium / L2 — Representation about access to all records and personnel
(1, 'Written Representations', 'The engagement team at Whitaker & Stevens is completing the audit of Redwood Construction Inc. for the year ended December 31, 2025. The partner reviews the representation letter draft and notices it does not include a representation about management providing the auditor with access to information. Under AU-C 580, the representation letter should include management''s acknowledgment that it has provided the auditor with:', '["Only the financial records and supporting documentation specifically requested during fieldwork", "Access to all information relevant to the preparation of the financial statements, including complete responses to inquiries", "Access to all information the auditor deemed necessary, limited to accounting records", "A complete list of every document in the entity''s possession related to the audit period"]'::jsonb, 1, 'AU-C 580.11 requires management to confirm it has provided the auditor with all information relevant to the preparation and fair presentation of the financial statements and complete responses to all inquiries. Choice A is incorrect because the representation covers all relevant information, not just items specifically requested.', 'medium', 2),

-- Q6: hard / L4 — Going concern doubts and representation letter interaction
(1, 'Written Representations', 'During the audit of Beacon Technologies Inc. for the year ended December 31, 2025, the engagement partner at Crawford & Hale CPA identifies substantial doubt about the entity''s ability to continue as a going concern. Management prepares a plan to mitigate the going concern issues and includes representations about the feasibility of that plan in the representation letter. The auditor has performed extensive procedures and concludes the plan is not feasible. Under AU-C 580 and AU-C 570, the auditor should:', '["Accept the representation as sufficient evidence of management''s intent and include an emphasis-of-matter paragraph", "Withdraw from the engagement because management''s representation contradicts the auditor''s conclusion", "Evaluate the going concern conclusion based on all audit evidence obtained, not solely on management''s representation about its plans", "Require management to revise the representation letter to remove references to the plan''s feasibility"]'::jsonb, 2, 'AU-C 580.04 and AU-C 570.16 require the auditor to evaluate going concern based on all available audit evidence, including but not limited to management representations. Representations alone do not override contradictory evidence from other procedures. Choice B is incorrect because disagreement about going concern plans does not automatically require withdrawal—the auditor modifies the opinion based on all evidence.', 'hard', 4),

-- Q7: medium / L3 — Summary of uncorrected misstatements attached to letter
(1, 'Written Representations', 'During the audit of Pinnacle Services Group for the year ended December 31, 2025, the engagement team at Fischer & Lang CPA identifies $45,000 in aggregate uncorrected misstatements that management has determined are immaterial individually and in the aggregate. The partner prepares the representation letter and considers how to address these items. Under AU-C 580, the auditor should:', '["Omit uncorrected misstatements from the representation letter if they are individually below the materiality threshold", "Include only a general statement that management believes the financial statements are free of material misstatement", "Require management to correct all identified misstatements before the representation letter is signed", "Attach a summary of uncorrected misstatements to the representation letter and obtain management''s representation that their effects are immaterial"]'::jsonb, 3, 'AU-C 580.12 requires that a summary of uncorrected misstatements identified during the audit be attached to the management representation letter. Management must represent that the effects are immaterial, both individually and in the aggregate. Choice A is incorrect because all identified uncorrected misstatements must be included regardless of their individual size.', 'medium', 3),

-- Q8: medium / L3 — Representations about accounting estimates
(1, 'Written Representations', 'While auditing Crestview Financial Corp. for the year ended December 31, 2025, the engagement team at Monroe & Associates evaluates the allowance for credit losses, which involves significant management judgment. The partner considers what specific representations about this estimate should be included in the management representation letter. Under AU-C 580, the representation letter should include management''s acknowledgment that:', '["The methods, assumptions, and data used in developing the estimate are reasonable in the context of the applicable financial reporting framework", "The estimate is guaranteed to be accurate within a 10% margin of error", "An independent third-party specialist reviewed and approved the estimation methodology", "The estimate will not require adjustment in future periods based on additional information"]'::jsonb, 0, 'AU-C 580.11 requires representations about the reasonableness of significant assumptions used in accounting estimates and that the methods and data are appropriate under the applicable framework. Choice B is incorrect because estimates inherently involve uncertainty, and no guarantee of accuracy is possible or required—the standard focuses on reasonableness of inputs.', 'medium', 3),

-- Q9: medium / L3 — Compliance with laws and regulations representation
(1, 'Written Representations', 'Silverline Manufacturing is in a heavily regulated industry and is audited by Henderson & Park CPA for the year ended December 31, 2025. The engagement partner drafts the representation letter and considers whether to include compliance-related representations. The controller questions whether a compliance representation is standard. Under AU-C 580, the representation letter should include management''s acknowledgment regarding:', '["Full compliance with all applicable laws and regulations, verified by the entity''s legal department", "All known instances of noncompliance or suspected noncompliance with laws and regulations whose effects should be considered in preparing the financial statements", "A legal opinion from outside counsel confirming compliance with all material regulations", "Only noncompliance matters that have resulted in actual fines or penalties during the audit period"]'::jsonb, 1, 'AU-C 580.11 requires management to represent that it has disclosed all known instances of noncompliance or suspected noncompliance with laws and regulations whose effects should be considered when preparing the financial statements. Choice D is incorrect because the representation covers all known and suspected noncompliance, not just matters that resulted in actual fines.', 'medium', 3),

-- Q10: medium / L3 — Group audit component management representations
(1, 'Written Representations', 'Holloway & Brent CPA is the group engagement partner for the audit of Apex Industries Inc. for the year ended December 31, 2025. Apex has three wholly-owned subsidiaries, each with its own management team. The group engagement partner considers whether separate representation letters are needed from component management. Under AU-C 600 and AU-C 580, for a group audit the group engagement partner should:', '["Obtain a single consolidated representation letter signed only by the parent company''s CEO and CFO", "Require each component auditor to obtain oral representations from component management in lieu of written letters", "Accept the group management representation letter as covering all component-level assertions without exception", "Determine whether to request written representations from component management, particularly when component management has primary responsibility for financial information"]'::jsonb, 3, 'AU-C 600.42 and AU-C 580 indicate the group engagement partner should consider requesting written representations from component management, especially when component management bears primary responsibility for component financial information. Choice A is incorrect because relying solely on group-level representations may not adequately address component-level assertions.', 'medium', 3),

-- Q11: medium / L2 — Internal control responsibility representation
(1, 'Written Representations', 'During the preparation of the management representation letter for Brighton Corp.''s December 31, 2025 audit, the engagement team at Warner & Cole CPA includes a representation about internal control. The CFO questions why an internal control representation is needed when this is not an integrated audit. Under AU-C 580, the representation letter for a financial statement audit should include management''s acknowledgment that:', '["Internal controls are effective and no material weaknesses exist", "The entity has engaged an external consultant to evaluate internal controls annually", "All internal control deficiencies have been remediated before year-end", "Management is responsible for the design, implementation, and maintenance of internal control relevant to the preparation of the financial statements"]'::jsonb, 3, 'AU-C 580.11 requires management to acknowledge responsibility for the design, implementation, and maintenance of internal control relevant to financial statement preparation, even in a financial statement-only audit. Choice A is incorrect because the representation addresses responsibility for internal control, not an assertion of effectiveness—effectiveness evaluation is characteristic of integrated audits.', 'medium', 2),

-- Q12: easy / L1 — Definition of written representations
(1, 'Written Representations', 'What are written representations as defined under AU-C 580?', '["Written statements provided by management to the auditor to confirm certain matters or support other audit evidence", "Formal legal documents filed with the SEC as part of the annual reporting process", "Internal memoranda prepared by the auditor summarizing oral discussions with management", "External confirmations received from third parties to verify account balances"]'::jsonb, 0, 'AU-C 580.07 defines written representations as written statements by management provided to the auditor to confirm certain matters or to support other audit evidence. They are prepared by management, not the auditor. Choice C is incorrect because written representations come from management, whereas auditor-prepared memoranda are part of audit documentation.', 'easy', 1),

-- Q13: medium / L2 — Management vs. those charged with governance
(1, 'Written Representations', 'During the audit of Cascade Holdings for the year ended December 31, 2025, the engagement partner at Dalton & Frost CPA considers whether written representations should be obtained from those charged with governance in addition to management. The audit committee chair asks whether governance-level representations are required. Under AU-C 580, written representations are primarily obtained from:', '["Those charged with governance, as they have ultimate oversight responsibility for the financial statements", "The entity''s external legal counsel, who can provide legally binding assurances", "Both management and those charged with governance for every representation in the letter", "Management, although the auditor may request representations from those charged with governance when the auditor considers it appropriate for matters within their responsibility"]'::jsonb, 3, 'AU-C 580.09 directs the auditor to request written representations from management with appropriate responsibilities for the financial statements and knowledge of the matters concerned. The auditor may also request representations from those charged with governance when appropriate. Choice A is incorrect because the primary source is management, not governance.', 'medium', 2),

-- Q14: medium / L3 — Rights and obligations / title to assets representation
(1, 'Written Representations', 'The audit of Sterling Resources Corp. for the year ended December 31, 2025 involves significant mineral rights and leased equipment. The engagement team at Brooks & Harmon CPA drafts the representation letter and considers what representations are needed regarding the entity''s assets. Under AU-C 580, the representation letter should include management''s confirmation that:', '["All assets have been appraised by independent valuation specialists within the past 12 months", "Depreciation methods applied to all assets comply with Internal Revenue Code requirements", "The entity has satisfactory title to, or control over, all assets and that liens or encumbrances on assets have been disclosed", "All assets are physically located on the entity''s premises and available for inspection"]'::jsonb, 2, 'AU-C 580.11 requires management to represent that the entity has satisfactory title to or control over assets and that any liens, pledges, or encumbrances have been properly disclosed. This addresses the rights and obligations assertion. Choice A is incorrect because the representation concerns ownership and encumbrances, not independent valuations.', 'medium', 3),

-- Q15: medium / L2 — Representations are necessary but not sufficient evidence
(1, 'Written Representations', 'A staff auditor at Blackwell & Torres CPA asks the engagement partner whether obtaining a comprehensive representation letter eliminates the need for certain substantive procedures on the audit of Wyatt Manufacturing for the year ended December 31, 2025. Under AU-C 580, written representations:', '["Can reduce the extent of substantive procedures required for low-risk assertions", "Provide necessary audit evidence but do not provide sufficient appropriate evidence on their own to support any financial statement assertion", "Are only required when the auditor cannot obtain other forms of audit evidence", "Serve as the primary form of evidence for assertions that are difficult to test through other means"]'::jsonb, 1, 'AU-C 580.04 establishes that although written representations provide necessary audit evidence, they do not provide sufficient appropriate evidence on their own about any of the matters with which they deal. The auditor must obtain corroborating evidence. Choice A is incorrect because representations do not reduce substantive procedure requirements.', 'medium', 2),

-- Q16: easy / L1 — AU-C section governing written representations
(1, 'Written Representations', 'Which AU-C section specifically addresses the auditor''s responsibilities regarding written representations from management?', '["AU-C 500, Audit Evidence", "AU-C 560, Subsequent Events and Subsequently Discovered Facts", "AU-C 550, Related Parties", "AU-C 580, Written Representations"]'::jsonb, 3, 'AU-C 580, Written Representations, is the authoritative standard that specifically addresses the auditor''s requirements for obtaining written representations from management during an audit. Choice A is incorrect because AU-C 500 addresses audit evidence generally, while AU-C 580 is the dedicated section for written representations.', 'easy', 1),

-- Q17: hard / L4 — Effect of unreliable representation on all other representations
(1, 'Written Representations', 'During the audit of Northgate Logistics Inc. for the year ended December 31, 2025, the engagement team at Kessler & Dunn CPA discovers that management''s written representation about the completeness of related party disclosures is contradicted by evidence obtained through independent inquiries and document inspection. The engagement partner must determine the broader implications. Under AU-C 580, when the auditor concludes that one or more written representations are not reliable, the auditor should:', '["Issue a qualified opinion specifically addressing the unreliable representation while accepting all other representations", "Withdraw from the engagement immediately, as the entire representation letter is invalidated", "Reconsider the reliability of all other representations obtained from management and take appropriate action, including assessing the possible effect on the audit opinion", "Request management to re-sign the representation letter with corrected information and continue the audit without further modification"]'::jsonb, 2, 'AU-C 580.20 requires the auditor to reassess the reliability of all representations when one or more are deemed unreliable. Unreliability in one area casts doubt on management''s integrity overall, requiring the auditor to consider the pervasive effect on the audit. Choice B is incorrect because withdrawal is not automatically required—the auditor must first evaluate the overall impact.', 'hard', 4),

-- Q18: easy / L1 — Fraud-related completeness representation
(1, 'Written Representations', 'What fraud-related representation must management include in the written representation letter under AU-C 580?', '["Acknowledgment of responsibility for internal control to prevent and detect fraud, and disclosure of all known or suspected fraud", "A guarantee that no employee has committed fraud during the audit period", "Certification that the entity''s anti-fraud training program meets minimum industry standards", "An assertion that the entity maintains fidelity bond coverage for all employees with access to assets"]'::jsonb, 0, 'AU-C 580.11 requires management to acknowledge responsibility for internal control to prevent and detect fraud and to disclose all knowledge of fraud or suspected fraud affecting the entity. Choice B is incorrect because management cannot guarantee the absence of fraud—the representation addresses disclosure of known or suspected fraud, not absolute prevention.', 'easy', 1),

-- Q19: hard / L3 — Attorney letter discrepancy with management representation
(1, 'Written Representations', 'During the audit of Hartland Pharmaceuticals for the year ended December 31, 2025, the engagement team at Whitfield & Associates CPA obtains responses from the entity''s outside counsel regarding pending litigation. The attorney''s response identifies a probable loss contingency of $2.3 million that management did not include in its representation letter. The auditor should:', '["Accept the attorney''s response as superseding the management representation letter for all litigation-related matters", "Discuss the discrepancy with management, request that the representation letter be updated to include the matter, and evaluate whether the omission affects the reliability of other representations", "Issue an adverse opinion because management intentionally omitted a known contingency from the representation letter", "Rely solely on the attorney''s letter for litigation disclosures because legal counsel has superior knowledge of legal matters"]'::jsonb, 1, 'Under AU-C 580.20 and AU-C 501.12, when a discrepancy exists between the attorney''s response and management''s representations, the auditor must investigate the inconsistency and request appropriate revisions. The omission may also indicate broader reliability concerns. Choice A is incorrect because the attorney''s letter supplements but does not replace management''s representations.', 'hard', 3),

-- Q20: easy / L1 — Addressee of the representation letter
(1, 'Written Representations', 'To whom is the management representation letter addressed in a financial statement audit?', '["The entity''s board of directors or audit committee", "The Securities and Exchange Commission", "The entity''s shareholders collectively", "The auditor or the audit firm performing the engagement"]'::jsonb, 3, 'AU-C 580.14 states that the written representation letter should be addressed to the auditor. The letter is a communication from management to the audit firm, confirming matters and supporting audit evidence. Choice A is incorrect because the representation letter is directed to the auditor, not to the board or audit committee.', 'easy', 1),

-- Q21: hard / L4 — Special purpose framework additional representations
(1, 'Written Representations', 'Jensen & Clark CPA is auditing the financial statements of Oakridge Community Foundation prepared using the cash basis of accounting (a special purpose framework) for the year ended December 31, 2025. The engagement partner considers whether the management representation letter requires modifications beyond the standard content. Under AU-C 580 and AU-C 800, for a special purpose framework audit the representation letter should:', '["Be identical to a GAAP-basis audit representation letter with no additional representations needed", "Omit representations about accounting policies since special purpose frameworks have no policy choices", "Include an additional representation that the special purpose framework is acceptable and that management understands users may not be familiar with the framework or departures from GAAP", "Require the representation letter to be reviewed by an independent party before the auditor accepts it"]'::jsonb, 2, 'AU-C 800.15 and AU-C 580 require the auditor to obtain additional representations when reporting on special purpose framework financial statements, including that the framework is acceptable and management acknowledges users may not fully understand the framework. Choice A is incorrect because special purpose frameworks require tailored representations beyond the standard GAAP-basis letter.', 'hard', 4),

-- Q22: medium / L3 — Side agreements and undisclosed arrangements
(1, 'Written Representations', 'During the audit of Lakeshore Capital Partners for the year ended December 31, 2025, the engagement team at Garrett & Flynn CPA discovers through inquiry with a major vendor that a side agreement exists granting Lakeshore extended payment terms not reflected in the recorded contracts. The auditor considers the implications for the representation letter. Under AU-C 580, the auditor should:', '["Request management to include a specific representation that there are no side agreements or arrangements that have not been properly disclosed and evaluate the initial omission", "Accept management''s explanation that the side agreement was immaterial and omit it from the representation letter", "Report the side agreement directly to the audit committee without discussing it with management", "Treat the side agreement solely as an internal control matter with no impact on the representation letter"]'::jsonb, 0, 'AU-C 580.11 requires representations about the completeness of information provided to the auditor, including all agreements and arrangements. Discovering an undisclosed side agreement signals a potential completeness issue requiring specific representation and further evaluation. Choice B is incorrect because the omission raises completeness concerns regardless of materiality.', 'medium', 3),

-- Q23: easy / L1 — Explicit written representations defined
(1, 'Written Representations', 'What distinguishes an explicit written representation from other forms of audit evidence?', '["It is generated electronically through the entity''s accounting information system", "It is a specific written statement made by management directly addressing a particular matter", "It is evidence obtained by the auditor directly from external third parties", "It is a verbal acknowledgment from management recorded in a formal meeting"]'::jsonb, 1, 'Under AU-C 580.07, explicit written representations are specific written statements from management that directly address particular matters relevant to the financial statements or the audit. They are distinguished by being written and specific. Choice C is incorrect because explicit representations come from management, not external parties—external evidence is obtained through confirmation procedures.', 'easy', 1),

-- Q24: easy / L1 — Subsequent events representation in the letter
(1, 'Written Representations', 'What representation about subsequent events is typically included in the management representation letter?', '["A guarantee that no events will occur after the report date that could affect the financial statements", "A statement that the entity has purchased insurance coverage for all subsequent event risks", "An acknowledgment that the entity''s legal counsel has reviewed all post-balance-sheet transactions", "A statement that all events occurring between the balance sheet date and the representation letter date requiring adjustment or disclosure have been properly addressed"]'::jsonb, 3, 'AU-C 580.11 requires a representation that all subsequent events requiring adjustment or disclosure have been properly reflected in the financial statements. This complements the auditor''s subsequent events procedures under AU-C 560. Choice A is incorrect because management cannot guarantee the absence of future events—the representation covers events through the letter date.', 'easy', 1),

-- Q25: medium / L2 — Additional representations required by other AU-C sections
(1, 'Written Representations', 'The engagement team at Rutherford & Dean CPA is completing the audit of Crestvale Corp. for the year ended December 31, 2025 and drafting the management representation letter. The senior auditor notes that several other AU-C sections also require specific written representations beyond those in AU-C 580. Under the clarified auditing standards, additional written representations may be required by:', '["Only AU-C 580, as it is the sole standard addressing all written representation requirements", "PCAOB standards only, as the clarified AU-C standards consolidated all representation requirements into AU-C 580", "Other AU-C sections addressing specific audit areas, such as AU-C 501 for litigation, AU-C 550 for related parties, and AU-C 560 for subsequent events", "Only the entity''s industry-specific regulatory body, which dictates representation letter content"]'::jsonb, 2, 'Various AU-C sections beyond AU-C 580 require specific written representations, including AU-C 501 (litigation, claims, assessments), AU-C 550 (related parties), and AU-C 560 (subsequent events). The representation letter aggregates requirements from multiple standards. Choice A is incorrect because AU-C 580 establishes the general framework while other sections impose additional requirements.', 'medium', 2),

-- Q26: easy / L2 — Accounting policy selection representation
(1, 'Written Representations', 'During the audit of Midland Services Inc. for the year ended December 31, 2025, the engagement team at Barrett & Shaw CPA drafts the representation letter. The CFO asks why a representation about accounting policies is included. Under AU-C 580, the accounting policy representation requires management to confirm that:', '["The selection and application of accounting policies are appropriate for the entity''s financial reporting framework", "All accounting policies have been approved by the audit committee before implementation", "The entity has adopted every new accounting standard effective during the current period", "Accounting policy disclosures in the footnotes were prepared by an independent consultant"]'::jsonb, 0, 'AU-C 580.11 requires management to represent that the significant accounting policies selected and applied are appropriate under the applicable financial reporting framework. This addresses management''s judgment in policy selection. Choice B is incorrect because audit committee approval of policies is a governance matter, not the substance of the AU-C 580 representation.', 'easy', 2),

-- Q27: hard / L4 — Initial audit and prior period representations
(1, 'Written Representations', 'Archer & Townsend CPA is engaged to perform the initial audit of Summit Healthcare Corp. for the year ended December 31, 2025. The prior year financial statements were audited by a different firm. The engagement partner must determine the representation letter requirements for this initial engagement. Under AU-C 580 and AU-C 510, the auditor should:', '["Obtain representations only for the current year because the predecessor auditor already obtained representations for prior periods", "Request representations covering all periods referred to in the auditor''s report and obtain specific representations regarding opening balances, including whether prior period misstatements affect the current year", "Require the predecessor auditor to provide a supplemental representation letter covering the prior period", "Issue a disclaimer of opinion on the comparative period if the predecessor''s representation letter is unavailable"]'::jsonb, 1, 'Under AU-C 580.15 and AU-C 510.09, in an initial audit the representation letter must cover all periods addressed in the auditor''s report, including representations about opening balances and whether prior period misstatements affect current year statements. Choice A is incorrect because the new auditor cannot rely on representations obtained by the predecessor.', 'hard', 4),

-- Q28: easy / L1 — Management responsibility acknowledgment
(1, 'Written Representations', 'What responsibility must management acknowledge in the written representation letter regarding the financial statements?', '["Responsibility for the preparation and fair presentation of the financial statements in accordance with the applicable reporting framework", "Responsibility for ensuring the audit is completed within the agreed-upon time frame", "Responsibility for selecting the audit firm and negotiating the audit fee", "Responsibility for distributing the audited financial statements to all stakeholders"]'::jsonb, 0, 'AU-C 580.10 requires management to provide a written representation acknowledging its responsibility for the preparation and fair presentation of the financial statements in accordance with the applicable financial reporting framework. Choice B is incorrect because audit timing is an engagement-level matter, not a responsibility management represents in the letter.', 'easy', 1),

-- Q29: hard / L4 — Contradiction between representation and audit evidence
(1, 'Written Representations', 'During the audit of Meridian Aerospace Corp. for the year ended December 31, 2025, the engagement team at Sinclair & Associates obtains management''s written representation that all intercompany transactions have been eliminated. However, the audit team independently discovers $1.8 million in uneliminated intercompany receivables through confirmation procedures. Management maintains its representation is correct. Under AU-C 580, the auditor should:', '["Investigate the inconsistency, obtain additional evidence, and if the contradiction cannot be resolved, consider the implications for the reliability of all representations and the overall audit opinion", "Accept management''s representation because written representations take precedence over external confirmation evidence", "Automatically issue an adverse opinion due to management''s false representation", "Withdraw from the engagement without further investigation because management has demonstrated a lack of integrity"]'::jsonb, 0, 'AU-C 580.18–.20 requires the auditor to investigate when representations are inconsistent with other audit evidence, obtain additional evidence, and reconsider the reliability of all representations if the matter is not resolved. The auditor must evaluate the effect on the opinion. Choice B is incorrect because written representations are lower in the evidence hierarchy than external confirmations.', 'hard', 4),

-- Q30: medium / L2 — Representations about contingent liabilities completeness
(1, 'Written Representations', 'The engagement team at Morrison & Kraft CPA is completing the audit of Trident Construction Inc. for the year ended December 31, 2025. The partner reviews the representation letter and ensures it includes appropriate representations about contingent liabilities. Under AU-C 580, the representation letter should include management''s confirmation that:', '["No contingent liabilities exist because all potential losses have been accrued in the financial statements", "All contingent liabilities that are required to be accrued or disclosed under the applicable financial reporting framework have been properly recorded or disclosed", "The entity''s legal counsel has independently verified the completeness of all contingent liability disclosures", "Contingent liabilities with less than a 50% probability of occurrence have been excluded from the financial statements"]'::jsonb, 1, 'AU-C 580.11 and AU-C 501 require management to represent that all contingent liabilities requiring accrual or disclosure have been properly reflected in the financial statements. This addresses the completeness assertion for contingencies. Choice A is incorrect because the representation acknowledges proper treatment—some contingencies may be disclosed rather than accrued.', 'medium', 2)
;

COMMIT;
